<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{supabase}from'../services/supabase';const props=defineProps<{mode:string}>();const router=useRouter(),email=ref(''),password=ref(''),fullName=ref(''),phone=ref(''),notice=ref(''),busy=ref(false);async function submit(){if(!supabase){notice.value='Configura las variables de Supabase para activar el acceso.';return}busy.value=true;const result=props.mode==='login'?await supabase.auth.signInWithPassword({email:email.value,password:password.value}):await supabase.auth.signUp({email:email.value,password:password.value,options:{data:{full_name:fullName.value,phone:phone.value}}});busy.value=false;if(result.error){notice.value=result.error.message;return}if(props.mode==='login')router.push('/perfil');else notice.value='Tu cuenta fue creada. Ya puedes iniciar sesión.'}</script>
<template><section class="auth-shell"><form class="auth-card" @submit.prevent="submit"><p class="eyebrow">{{mode==='login'?'BIENVENIDA DE VUELTA':'COMIENZA HOY'}}</p><h1>{{mode==='login'?'Inicia sesión':'Crea tu cuenta'}}</h1><p>{{mode==='login'?'Continúa tu camino con Streamer Hub.':'Recibe orientación y guarda tus opciones favoritas.'}}</p><template v-if="mode==='register'"><label>Nombre completo<input v-model="fullName" required autocomplete="name"></label><label>Teléfono<input v-model="phone" required autocomplete="tel"></label></template><label>Correo electrónico<input v-model="email" required type="email" autocomplete="email"></label><label>Contraseña<input v-model="password" required type="password" minlength="6" autocomplete="current-password"></label><p v-if="notice" class="notice">{{notice}}</p><button class="button" :disabled="busy">{{busy?'Un momento…':mode==='login'?'Entrar':'Crear cuenta'}}</button><RouterLink class="text-link" :to="mode==='login'?'/registro':'/ingresar'">{{mode==='login'?'¿No tienes cuenta? Regístrate':'¿Ya tienes cuenta? Inicia sesión'}}</RouterLink></form></section></template>

